# 予算を揃えた 3 アーム。総数はすべて 25 に固定される。
BUDGET = 25

def arm_baseline(system, msa):
    # 現行の配分: 1 MSA から 25 構造
    return boltz2(system, msa=msa, diffusion_samples=25)

def arm_proposed(system, msa):
    # 上流に配る: 5 変種 x 5 サンプル
    out = []
    for rank, variant in enumerate(subsample_msa(msa, n_variants=5, seed=0)):
        out += boltz2(system, msa=variant, diffusion_samples=5)
    return out

def arm_lineage(system, msa):
    # 別系統に配る: co-folding 20 + docking 5
    cofold = boltz2(system, msa=msa, diffusion_samples=20)
    receptor = strip_ligand(best_by_confidence(cofold))
    return cofold + diffdock(receptor, system.smiles, num_poses=5)

# 主指標は 25 本中の最良。予算が揃っているので直接比較できる。
def oracle_lddt_pli(poses, reference):
    return max(ost_lddt_pli(p, reference) for p in poses)
